INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0012', 'pt', 'sim', 'yes', 'adv', NULL, 'in speech people often repeat the verb instead: «Tens?» — «Tenho»', 'Sim, claro.', 'Yes, of course.', '["core"]', 12, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
