INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0019', 'pt', 'a conta', 'the bill', 'noun', 'f', 'in a café you ask: «A conta, se faz favor»', 'A conta, se faz favor.', 'The bill, please.', '["core","cafe"]', 19, NULL, 'comida') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0020', 'pt', 'onde fica...?', 'where is...?', 'phrase', NULL, 'ficar for places = to be located', 'Onde fica a farmácia?', 'Where is the pharmacy?', '["core","direcoes"]', 20, NULL, 'cidade') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
