INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0011', 'en', 'to make sense', 'to be logical, understandable', 'phrase', NULL, 'does it make sense? = is it clear/logical?', 'Does this chart make sense to you?', NULL, '["glue","work"]', 11, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0012', 'en', 'to be supposed to', 'to be expected/meant to', 'phrase', NULL, 'softer than must: intended, but not guaranteed', 'The report was supposed to be ready yesterday.', NULL, '["glue"]', 12, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0013', 'en', 'to end up', 'to finally arrive at (a state)', 'verb', NULL, 'with a gerund: ended up rewriting everything', 'We ended up rewriting the whole pipeline.', NULL, '["glue"]', 13, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0014', 'en', 'in a nutshell', 'summed up in a few words', 'phrase', NULL, NULL, 'In a nutshell, sales are up, margins are down.', NULL, '["glue","work"]', 14, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
