INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0016', 'en', 'trade-off', 'an exchange of one benefit for another', 'noun', NULL, 'not a compromise: you give up one thing to gain another', 'There''s a trade-off between speed and accuracy.', NULL, '["work","data"]', 16, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0017', 'en', 'to double-check', 'to verify once more', 'verb', NULL, NULL, 'Let me double-check the numbers before we send it.', NULL, '["work"]', 17, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0018', 'en', 'eventually', 'in the end, after some time', 'adv', NULL, 'false friend: NOT ''possibly'' — it means ''sooner or later''', 'Eventually, we found the bug.', NULL, '["glue","trap"]', 18, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0019', 'en', 'to rely on', 'to depend on, to trust', 'verb', NULL, NULL, 'We rely on external survey data.', NULL, '["work","data"]', 19, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0020', 'en', 'fair enough', 'a mild way to accept an argument', 'phrase', NULL, 'gentle concession in a discussion', '— We can''t afford it. — Fair enough.', NULL, '["glue"]', 20, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0021', 'en', 'to follow up', 'to check back on something after an earlier message or meeting', 'verb', NULL, 'follow up ON a matter, WITH a person; the noun is hyphenated: a follow-up', 'I''ll follow up with the supplier on Monday if we still haven''t heard back.', NULL, '["work","follow-ups"]', 21, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0022', 'en', 'circle back (to something)', 'return to a topic, or to a person, later once something more urgent is done', 'verb', NULL, 'Business register and heavily overused, so save it for deferrals you actually intend to honour. The neutral alternative is ''come back to''.', 'Let''s circle back to the pricing question once Marta has the final numbers.', NULL, '["meetings","deferring","business-register"]', 22, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0023', 'en', 'to be up to', 'to be doing or busy with something', 'phrase', NULL, '"What have you been up to?" is a standard opener — answer with an activity, not a feeling.', 'What have you been up to since we last spoke?', NULL, '["social","smalltalk","opener"]', 23, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0024', 'en', 'caveat', 'a warning attached to a claim, marking where it may not hold', 'noun', NULL, 'Collocations: attach a caveat, with the caveat that..., the usual caveats apply. Stress the first syllable, KAV-ee-at.', 'The uplift is real, but it comes with one caveat: we only have four weeks of data.', NULL, '["data","hedging","presenting"]', 24, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0025', 'en', 'outstanding', 'still not paid, or still waiting to be dealt with', 'adj', NULL, 'Looks like the praise word, but here it means unpaid. An ''outstanding balance'' is money you owe, not money you have.', 'There are two outstanding invoices on the account, both from March.', NULL, '["money","invoices","admin"]', 25, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0026', 'en', 'chase up', 'to contact someone again about something they have not yet done or sent', 'verb', NULL, 'Separable: chase it up, chase up the referral. Americans say ''follow up on''.', 'If the clinic hasn''t rung by Friday, I''ll chase them up.', NULL, '["life","phrasal-verb","admin"]', 26, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0027', 'en', 'having said that', 'used to add a point that partly contradicts what you have just said', 'phrase', NULL, '''That said'' is the shorter, slightly more formal twin; both are fine in writing.', 'The model performed well last quarter; having said that, I wouldn''t rely on it for the new market.', NULL, '["glue","contrast","signposting"]', 27, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0028', 'en', 'blocker', 'something that stops work going any further until it is resolved', 'noun', NULL, 'names the obstacle, not the person; say what is blocking you and who can clear it', 'The only blocker is access to the production database.', NULL, '["work","blockers"]', 28, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0029', 'en', 'park (something)', 'deliberately set a topic aside so the meeting can move on', 'verb', NULL, 'Usually ''park it for now''. It implies you will return to the topic, and people notice when you never do.', 'Can we park the naming debate and finish the roadmap first?', NULL, '["meetings","deferring"]', 29, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0030', 'en', 'to fancy', 'to want something or feel like having it', 'verb', NULL, 'The everyday British way to offer: Do you fancy...? Not used in this sense in American English.', 'Do you fancy a coffee before the meeting?', NULL, '["social","food","uk"]', 30, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0031', 'en', 'account for', 'to make up a given share of a total; also, to allow for something in an analysis', 'verb', NULL, 'Two senses that live side by side. ''Accounts for 30%'' = makes up. ''Once we account for seasonality'' = adjust for. Context separates them.', 'Mobile users account for just under a third of all sessions.', NULL, '["data","presenting"]', 31, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0032', 'en', 'chase', 'to contact someone repeatedly to get money or an answer they owe you', 'verb', NULL, 'Normal office register, not aggressive. You chase an invoice, a payment or a person; ''chase them up'' is slightly softer.', 'I''ll chase the client again on Friday if the payment still hasn''t landed.', NULL, '["money","invoices","work"]', 32, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0033', 'en', 'sort out', 'to deal with a problem or arrange something so that it works', 'verb', NULL, 'Separable: sort it out, never ''sort out it''. Also passive-ish: I''ll get it sorted.', 'The agency said they''d sort out the broken heater by Tuesday.', NULL, '["life","phrasal-verb","housing"]', 33, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0034', 'en', 'as far as I''m aware', 'used to state something while admitting you may not have the full picture', 'phrase', NULL, 'Covers you if you turn out to be wrong. The negative answer form is ''not that I''m aware of''.', 'As far as I''m aware, nobody has touched that table since March.', NULL, '["glue","hedging","spoken","work"]', 34, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0035', 'en', 'to own', 'to be the person answerable for getting something done', 'verb', NULL, 'owning a task means being accountable for it, not doing every part yourself', 'Who owns the migration once the consultants leave?', NULL, '["work","ownership"]', 35, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0036', 'en', 'jump in', 'interrupt a speaker briefly to add or correct something', 'verb', NULL, 'Soften it with ''sorry to'' or ''can I just''. Without the softener it sounds abrupt on a call.', 'Sorry to jump in, but that deadline moved last week.', NULL, '["meetings","interrupting"]', 36, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0037', 'en', 'Kind regards', 'a warm but professional way to close an email', 'phrase', NULL, 'The UK default. ''Regards'' alone reads cooler, ''Best wishes'' warmer; ''Yours sincerely'' now belongs to formal letters.', 'I closed with ''Kind regards'' rather than anything friendlier.', NULL, '["writing","email","sign-off"]', 37, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0038', 'en', 'to head off', 'to leave a place', 'verb', NULL, 'Softer than "to leave" — announces your departure without sounding abrupt.', 'I''ll head off around six if that''s alright.', NULL, '["social","leaving"]', 38, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0039', 'en', 'bear out', 'to confirm that a claim or an expectation was correct', 'verb', NULL, 'Often passive and often negative: ''that isn''t borne out by the data''. Past participle is borne, not born.', 'The full quarter bears out what the early sample suggested.', NULL, '["data","evidence"]', 39, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0040', 'en', 'invoice', 'to send someone a formal request for payment', 'verb', NULL, 'Used as a verb: invoice the client, invoice for the extra hours. ''Raise an invoice'' means to create one.', 'We invoice at the end of every month and expect payment within thirty days.', NULL, '["money","invoices","work"]', 40, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0041', 'en', 'get back to someone', 'to reply to someone later, once you have an answer', 'phrase', NULL, '''I''ll get back to you'' is often a polite way of saying ''not now''.', 'The council took three weeks to get back to me about the permit.', NULL, '["life","phone","admin"]', 41, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0042', 'en', 'off the top of my head', 'from memory, without checking, so possibly not exact', 'idiom', NULL, 'Buys thinking time and licenses an approximate number. Usually sits at the front of the answer.', 'Off the top of my head it''s about forty thousand rows, but let me check.', NULL, '["glue","hedging","buying-time","idiom"]', 42, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0043', 'en', 'scope', 'the agreed boundaries of what a piece of work includes', 'noun', NULL, 'fixed phrases: in scope, out of scope, the scope of work', 'Let''s agree the scope before anyone starts building.', NULL, '["work","scope"]', 43, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0044', 'en', 'push back (on something)', 'disagree with a plan or request and say why, instead of simply accepting it', 'verb', NULL, 'Neutral and even valued in UK workplaces. The conditional ''I''d push back'' is gentler than ''I push back''. Noun form: pushback.', 'I''d push back slightly on the timeline, because two weeks isn''t enough for testing.', NULL, '["meetings","disagreeing"]', 44, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0045', 'en', 'I''m afraid', 'a polite marker that bad news or a refusal is coming', 'phrase', NULL, 'Nothing to do with fear. It is the standard British softener for saying no in writing.', 'I''m afraid we can''t take this on before September.', NULL, '["writing","saying-no","register"]', 45, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0046', 'en', 'to get up to', 'to do or spend free time on something', 'verb', NULL, 'The weekend question: What did you get up to at the weekend? British English says at the weekend, not on.', 'We didn''t get up to much on Saturday.', NULL, '["social","weekend","uk"]', 46, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0047', 'en', 'year on year', 'compared with the same period twelve months earlier', 'phrase', NULL, 'British form; Americans write year over year (YoY). Hyphenate before a noun: year-on-year growth.', 'Revenue is up eleven per cent year on year, and flat on the previous quarter.', NULL, '["data","trends","comparison"]', 47, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0048', 'en', 'settle', 'to pay a bill or debt in full', 'verb', NULL, 'Formal, standard in letters from banks and utilities. ''Settle up'' is the casual version between friends.', 'Please settle the balance before the end of the month to avoid interest.', NULL, '["money","invoices","banking"]', 48, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0049', 'en', 'bear with me', 'please be patient for a moment while I do something', 'phrase', NULL, 'Spelt ''bear'', not ''bare''. Constant on the phone and at counters.', 'Bear with me while I pull your file up on the system.', NULL, '["life","phone","service"]', 49, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0050', 'en', 'I take your point', 'used to accept that what someone said is valid before you answer it', 'phrase', NULL, 'Nearly always followed by ''but'' or ''though'' — that pivot is what makes it polite rather than agreement.', 'I take your point about the deadline, though I''d still want to test it properly.', NULL, '["glue","disagreeing","concession","work"]', 50, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0051', 'en', 'deliverable', 'a specific piece of work you have agreed to hand over', 'noun', NULL, 'usually plural in plans: the deliverables for phase one', 'There are three deliverables in this phase, and the report is the first.', NULL, '["work","scope"]', 51, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0052', 'en', 'take it offline', 'agree to discuss a side issue after the meeting, with fewer people', 'phrase', NULL, '''Offline'' here means ''not in this meeting''. It has nothing to do with being off the internet.', 'That''s a database question, so shall we take it offline and report back on Thursday?', NULL, '["meetings","deferring"]', 52, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0053', 'en', 'to be into', 'to be keen on something as an interest', 'phrase', NULL, 'Informal; followed by a noun or an -ing form.', 'She''s really into open-water swimming.', NULL, '["social","hobbies"]', 53, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0054', 'en', 'underlying', 'describing the real trend once one-off effects are stripped out', 'adj', NULL, 'Frequent pairs: underlying trend, underlying growth, underlying cause. Sits opposite headline.', 'Strip out the campaign spike and underlying demand is flat.', NULL, '["data","trends"]', 54, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0055', 'en', 'reimburse', 'to pay someone back for money they have spent', 'verb', NULL, 'You reimburse a person, not a cost: reimburse me for the ticket, not reimburse the ticket. Noun: reimbursement.', 'The company will reimburse you for the taxi once you upload the receipt.', NULL, '["money","work","admin"]', 55, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0056', 'en', 'put someone through', 'to connect a caller to another person or department by telephone', 'verb', NULL, 'From your side: I was put through to the wrong department. Related: hold the line.', 'I''ll put you through to the billing team now.', NULL, '["life","phone","phrasal-verb"]', 56, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0057', 'en', 'the thing is', 'used to introduce the problem or objection you are about to raise', 'phrase', NULL, 'Signals bad news gently. Informal — good in meetings, weak in formal writing.', 'I''d love to help, but the thing is, I''m already covering two reports this week.', NULL, '["glue","softening","spoken"]', 57, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0058', 'en', 'recap', 'go back over the main points briefly so everyone has them clear', 'verb', NULL, 'Also a noun: ''a quick recap''. Opening with ''To recap'' tells the room a summary is coming, not a new argument.', 'Before we finish, let me recap what each team has agreed to.', NULL, '["meetings","summarising"]', 58, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0059', 'en', 'a heads-up', 'advance warning about something that is coming', 'noun', NULL, 'Hyphenated as a noun; you give someone a heads-up. Informal, so Slack and internal email only.', 'Just a heads-up: the dashboard will be down on Friday morning.', NULL, '["writing","slack","email"]', 59, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0060', 'en', 'to get on with', 'to have a friendly relationship with someone', 'verb', NULL, 'British; Americans say get along with. "Get on with it" is a different thing entirely — it means hurry up.', 'I get on with everyone on the analytics team.', NULL, '["social","uk","trap"]', 60, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0061', 'en', 'materially', 'to a degree large enough to change a decision', 'adv', NULL, 'Formal, common in reports and audit language. ''Not materially different'' is a tactful way of saying the gap is real but irrelevant.', 'Excluding the outliers does not materially change the result.', NULL, '["data","presenting"]', 61, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0062', 'en', 'incur', 'to bring a cost, charge or penalty on yourself', 'verb', NULL, 'Formal, and the object is always something unwanted: costs, charges, fees, a penalty, interest.', 'Cancelling after the deadline will incur a fee of fifty euros.', NULL, '["money","contracts","admin"]', 62, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0063', 'en', 'book in', 'to arrange an appointment or place for someone, especially at a clinic', 'verb', NULL, 'British; Americans say ''schedule''. You book someone in FOR something.', 'They booked me in for a scan on the 14th.', NULL, '["life","appointments","healthcare"]', 63, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0064', 'en', 'broadly speaking', 'in general terms, without going into exceptions', 'phrase', NULL, 'Same frame as ''roughly speaking'' for numbers and ''strictly speaking'' for precision.', 'Broadly speaking, users who sign up at the weekend churn faster.', NULL, '["glue","hedging","signposting"]', 64, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0065', 'en', 'to flag', 'to draw attention to a problem or point early', 'verb', NULL, 'BrE often adds up: flag it up in the meeting; it signals a risk, not blame', 'I''d rather flag the risk now than explain it in the review.', NULL, '["work","blockers"]', 65, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0066', 'en', 'loop someone in', 'bring another person into a conversation or thread so they know what is happening', 'verb', NULL, 'Separable, and the pronoun must sit in the middle: loop her in, never ''loop in her''.', 'I''ll loop Sofia in before we commit to a date.', NULL, '["meetings","collaboration"]', 66, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0067', 'en', 'to make a move', 'to start leaving', 'idiom', NULL, 'Usually "I''d better make a move" — the polite British signal that you are about to go.', 'It''s getting late, so I''d better make a move.', NULL, '["social","leaving","uk"]', 67, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0068', 'en', 'skew', 'to pull a figure or a sample in one direction and so distort it', 'verb', NULL, 'Also an adjective, skewed, and a noun. ''The sample skews young'' means it leans young.', 'A handful of enterprise accounts skew the average basket size upwards.', NULL, '["data","uncertainty"]', 68, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0069', 'en', 'arrears', 'money that is owed because payments were missed', 'noun', NULL, 'Always plural. ''Paid in arrears'' also just means paid after the period worked, as with a monthly salary, and that sense is neutral.', 'Two missed payments and the account is already in arrears.', NULL, '["money","banking","admin"]', 69, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0070', 'en', 'bring forward', 'to move an appointment or event to an earlier date or time', 'verb', NULL, 'The opposite is ''push back'' or ''put back''. American ''move up'' also means earlier, which confuses everyone.', 'Can we bring the appointment forward to Monday morning?', NULL, '["life","appointments","phrasal-verb"]', 70, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0071', 'en', 'heads-up', 'an early warning that something is coming', 'noun', NULL, 'almost always with give: give someone a heads-up; informal but fine at work', 'Thanks for the heads-up about tomorrow''s outage.', NULL, '["work","follow-ups"]', 71, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0072', 'en', 'run something by someone', 'show an idea to someone informally to get their reaction before it is final', 'verb', NULL, 'Signals you want a reaction, not formal sign-off. ''Run it past someone'' is the more common British variant.', 'Let me run the draft budget by finance before I present it.', NULL, '["meetings","collaboration"]', 72, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0073', 'en', 'cheers', 'thanks; also goodbye, or a toast', 'phrase', NULL, 'Informal British. Fine with colleagues and in shops, too casual for a formal email.', 'Cheers for sorting that out so quickly.', NULL, '["social","register","uk"]', 73, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0074', 'en', 'rule out', 'to eliminate an explanation as impossible or unsupported', 'verb', NULL, 'Separable: rule it out. The weaker cousin, ''we can''t rule out'', is a standard hedge.', 'We can rule out a tracking bug, since the server logs show the same drop.', NULL, '["data","evidence"]', 74, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0075', 'en', 'direct debit', 'an arrangement letting a company take an agreed amount from your account automatically', 'noun', NULL, 'The company pulls a variable amount; a standing order is you pushing a fixed one. Neither term exists in American English.', 'I''ve set up a direct debit for the electricity so I stop forgetting it.', NULL, '["money","banking","subscriptions"]', 75, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0076', 'en', 'in writing', 'recorded in a letter or email rather than agreed only in speech', 'phrase', NULL, 'The standard move once a complaint turns serious. Also ''put it in writing''.', 'Ask the landlord to confirm the rent reduction in writing.', NULL, '["life","complaints","admin"]', 76, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0077', 'en', 'I''m not sure I follow', 'a polite way of saying you have not understood and need it explained again', 'phrase', NULL, 'Places the gap on you rather than the speaker, so nobody loses face. Far softer than ''that wasn''t clear''.', 'I''m not sure I follow: is the discount applied before or after VAT?', NULL, '["meetings","checking-understanding"]', 77, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0078', 'en', 'to bump into', 'to meet someone by chance', 'verb', NULL, NULL, 'I bumped into an old colleague at the market.', NULL, '["social","smalltalk"]', 78, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0079', 'en', 'discrepancy', 'a difference between two figures that ought to match', 'noun', NULL, 'Neutral and blame-free, which makes it safer than ''error'' when you raise it with another team.', 'There is a small discrepancy between the billing export and the dashboard.', NULL, '["data","quality"]', 79, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0080', 'en', 'excess', 'the part of an insurance claim you pay yourself before the insurer pays the rest', 'noun', NULL, 'British insurance term; Americans say deductible. A ''voluntary excess'' lowers your premium in exchange for paying more per claim.', 'The repair came to eight hundred euros, but with a three-hundred euro excess the insurer only paid five.', NULL, '["money","insurance"]', 80, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0081', 'en', 'GP', 'the local family doctor who treats everyday problems and refers you onwards', 'noun', NULL, 'Short for general practitioner; say the letters. Register with a GP, see your GP.', 'You''ll need to see a GP before the hospital will look at it.', NULL, '["life","healthcare","uk"]', 81, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0082', 'en', 'to put it another way', 'used to restate what you have just said in clearer terms', 'phrase', NULL, 'Useful when you see blank faces. ''Let me put it this way'' is the more informal version.', 'The lift is real but tiny — to put it another way, we spent six weeks for half a percent.', NULL, '["glue","signposting","clarifying"]', 82, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0083', 'en', 'to sign off on', 'to give final approval to a piece of work', 'verb', NULL, 'BrE often drops on: sign off the budget; the noun is sign-off', 'Nothing goes live until legal has signed off on the wording.', NULL, '["work","ownership"]', 83, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0084', 'en', 'bring someone up to speed', 'give someone the background they are missing so they can take part properly', 'phrase', NULL, 'Separable, and the topic follows ''on''. ''Get up to speed'' is the version you use about yourself.', 'Tiago has just joined the project, so I''ll bring him up to speed on the migration.', NULL, '["meetings","checking-understanding"]', 84, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0085', 'en', 'gentle reminder', 'a soft prompt about something that is overdue', 'phrase', NULL, 'Many British readers hear it as passive-aggressive; ''just checking in on this'' is safer.', 'She opened with a gentle reminder that the deadline was yesterday.', NULL, '["writing","chasing","trap"]', 85, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0086', 'en', 'I won''t keep you', 'a polite way of ending a conversation', 'phrase', NULL, 'Puts the leaving on you rather than on them, so it sounds considerate instead of bored.', 'Anyway, I won''t keep you — enjoy the rest of your evening.', NULL, '["social","leaving"]', 86, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0087', 'en', 'reconcile', 'to work out why two sets of figures differ and bring them into agreement', 'verb', NULL, 'Pattern: reconcile A with or against B. The noun is reconciliation.', 'I spent the morning reconciling the finance numbers with our own totals.', NULL, '["data","quality"]', 87, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0088', 'en', 'premium', 'the amount you pay for an insurance policy, usually monthly or yearly', 'noun', NULL, 'Not the adjective ''premium'' meaning high-end. Premiums are quoted, they rise and fall, and you pay them.', 'My premium went up by thirty per cent after the claim.', NULL, '["money","insurance"]', 88, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0089', 'en', 'surgery', 'the building or practice where a GP sees patients', 'noun', NULL, 'British trap: here it is not an operation. ''She''s at the surgery'' means at the doctor''s.', 'The surgery opens at eight, so ring then for a same-day appointment.', NULL, '["life","healthcare","uk"]', 89, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0090', 'en', 'granted', 'used to admit a point is true before arguing that it doesn''t matter much', 'adv', NULL, 'Sits at the front of the sentence with a comma. ''Admittedly'' does the same job more formally.', 'Granted, the sample is small, but the pattern is hard to ignore.', NULL, '["glue","concession","disagreeing"]', 90, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0091', 'en', 'bandwidth', 'the time and attention someone has spare for more work', 'noun', NULL, 'uncountable in this sense and slightly informal; keep it out of formal writing', 'I haven''t got the bandwidth to take on another dashboard this week.', NULL, '["work","priorities"]', 91, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0092', 'en', 'flag (something)', 'raise something so the group notices it now, without necessarily solving it', 'verb', NULL, 'British colleagues often say ''flag up''. Flagging is explicitly not the same as taking ownership, which is why it is useful.', 'I want to flag a risk: the supplier still hasn''t confirmed the delivery date.', NULL, '["meetings","raising-issues"]', 92, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0093', 'en', 'to nudge', 'to prompt someone lightly about an unanswered request', 'verb', NULL, 'Warmer and lighter than ''chase''; very common in chat.', 'I''ll nudge him again if there''s nothing by Thursday.', NULL, '["writing","chasing"]', 93, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0094', 'en', 'to get round to', 'to finally find the time to do something', 'verb', NULL, 'British spelling is round; followed by an -ing form: get round to booking.', 'I still haven''t got round to booking the flights.', NULL, '["social","hobbies","uk"]', 94, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0095', 'en', 'patchy', 'present in some places and missing in others; uneven in quality', 'adj', NULL, 'Very British and very useful for incomplete data or uneven results: patchy coverage, patchy adoption.', 'Coverage before 2023 is patchy, so I would not chart that period.', NULL, '["data","quality"]', 95, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0096', 'en', 'cover', 'the protection an insurance policy gives you', 'noun', NULL, 'Uncountable in British English: cover for theft, never ''a cover''. Americans say coverage.', 'Check whether the policy includes cover for flooding before you sign.', NULL, '["money","insurance"]', 96, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0097', 'en', 'referral', 'an official request from one doctor for you to be seen by a specialist', 'noun', NULL, 'Verb: refer someone to. The document itself is a referral letter.', 'The dermatologist won''t take you without a referral from your GP.', NULL, '["life","healthcare"]', 97, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0098', 'en', 'I''m not entirely convinced', 'a mild way of saying you disagree or still have serious doubts', 'phrase', NULL, 'British understatement: it usually means you disagree quite firmly.', 'I''m not entirely convinced the drop is seasonal.', NULL, '["glue","disagreeing","softening","british"]', 98, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0099', 'en', 'to push back', 'to resist or question a request rather than simply accept it', 'verb', NULL, 'push back ON a request; a separate sense moves a date later: push the launch back', 'She pushed back on the timeline and asked for two more weeks.', NULL, '["work","priorities"]', 99, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0100', 'en', 'action point', 'a specific task agreed in a meeting, with an owner and usually a deadline', 'noun', NULL, 'British minutes use ''action point'' or just ''action''; ''action item'' is American. ''Action'' is also used as a verb in offices (''who''s actioning this?''), which is heavy jargon.', 'There are three action points from today and two of them are mine.', NULL, '["meetings","summarising","british"]', 100, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0101', 'en', 'Many thanks', 'a brief, warm closing thank-you', 'phrase', NULL, 'Works as a sign-off when you have asked for something; a shade warmer than ''Thanks''.', 'Many thanks for turning this around so quickly.', NULL, '["writing","email","sign-off"]', 101, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0102', 'en', 'up for', 'willing to join in with something', 'phrase', NULL, 'Do not mix it up with "up to": Are you up for it? means willing, What are you up to? means doing.', 'Are you up for a walk on Sunday?', NULL, '["social","weekend","trap"]', 102, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0103', 'en', 'plateau', 'to stop rising and stay at roughly the same level', 'verb', NULL, 'Pronounced PLAT-oh in Britain. Also a noun: we''ve hit a plateau. Neighbours: level off, flatten out.', 'Sign-ups climbed for six weeks and then plateaued.', NULL, '["data","trends"]', 103, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0104', 'en', 'quote', 'a stated price for a job or service, given before you agree to it', 'noun', NULL, 'Nothing to do with quoting words here. You get or request a quote; ''quotation'' is the formal written version.', 'I got three quotes for the car insurance and the cheapest was half the price of the worst.', NULL, '["money","insurance","contracts"]', 104, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0105', 'en', 'repeat prescription', 'a renewal of regular medication issued without a new appointment', 'noun', NULL, 'British system term; the American equivalent is a ''refill''.', 'I''ve ordered my repeat prescription through the app.', NULL, '["life","healthcare","uk"]', 105, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0106', 'en', 'backlog', 'work that has piled up and is still waiting to be done', 'noun', NULL, 'you clear, work through or prioritise a backlog', 'The backlog has grown faster than we can clear it.', NULL, '["work","priorities"]', 106, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0107', 'en', 'wrap up', 'bring a meeting or a topic to an end, usually with a short summary', 'verb', NULL, 'Noun form is hyphenated: ''a quick wrap-up''.', 'We''re nearly out of time, so let''s wrap up and take the rest by email.', NULL, '["meetings","summarising"]', 107, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0108', 'en', 'anyway', 'a signal that you are closing a topic or a conversation', 'adv', NULL, 'Sentence-initial and with a falling tone it means "let''s wrap this up", not "nevertheless".', 'Anyway, I should let you get back to work.', NULL, '["social","leaving"]', 108, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0109', 'en', 'uptick', 'a small rise, especially after a flat or falling stretch', 'noun', NULL, 'Deliberately small; don''t use it for a big jump. Opposite: a dip. Pattern: an uptick in something.', 'There is a modest uptick in weekend traffic, though it sits within normal variation.', NULL, '["data","trends"]', 109, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0110', 'en', 'tax return', 'the yearly form on which you declare your income to the tax office', 'noun', NULL, 'You file or submit a return. The return is the form; the money you get back is a refund or rebate.', 'I file my tax return in April, once the bank sends the interest statement.', NULL, '["money","tax","admin"]', 110, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0111', 'en', 'over the counter', 'sold in a pharmacy without a prescription', 'adj', NULL, 'Hyphenated before a noun: over-the-counter painkillers. OTC on packaging.', 'Ibuprofen is available over the counter, so you don''t need to see anyone.', NULL, '["life","healthcare"]', 111, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0112', 'en', 'give or take', 'used after a number to show it is approximate', 'phrase', NULL, 'Can carry the margin: ''give or take a week''. Spoken only — keep it out of reports.', 'The job runs in twenty minutes, give or take.', NULL, '["glue","hedging","numbers","spoken"]', 112, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0113', 'en', 'to escalate', 'to raise an issue to someone more senior for a decision', 'verb', NULL, 'neutral, not aggressive; also intransitive, as in costs escalated quickly', 'If they miss the second deadline, we escalate it to their director.', NULL, '["work","blockers"]', 113, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0114', 'en', 'to have the bandwidth', 'to have enough spare time or capacity', 'idiom', NULL, 'A polite way to refuse without writing a flat no.', 'I don''t have the bandwidth to take this on this quarter.', NULL, '["writing","saying-no","work"]', 114, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0115', 'en', 'to take up', 'to start a new hobby or activity', 'verb', NULL, NULL, 'He took up bouldering after moving to the island.', NULL, '["social","hobbies"]', 115, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0116', 'en', 'taper off', 'to decrease gradually and then stop', 'verb', NULL, 'Gentler than drop or collapse: the fall is slow and smooth rather than sudden.', 'Interest in the feature tapers off after the first fortnight.', NULL, '["data","trends"]', 116, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0117', 'en', 'write off', 'to accept that a debt will never be repaid, or to count a cost against taxable income', 'verb', NULL, 'Separable: write it off. A car damaged beyond repair is ''a write-off'', hyphenated as a noun.', 'You can write off the laptop against tax if you use it mainly for work.', NULL, '["money","tax","insurance"]', 117, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0118', 'en', 'waiting list', 'the queue of people waiting for a treatment or appointment', 'noun', NULL, 'You are ON a waiting list. ''Physio'' is the normal short form of physiotherapy.', 'I''m on the waiting list for physio, apparently for four months.', NULL, '["life","healthcare","appointments"]', 118, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0119', 'en', 'let me come back to you on that', 'used to postpone an answer you don''t have yet', 'phrase', NULL, 'Far better than inventing a number, but only if you actually do come back.', 'I don''t want to guess the licence cost — let me come back to you on that.', NULL, '["glue","buying-time","work"]', 119, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0120', 'en', 'scope creep', 'the slow growth of a task beyond what was agreed', 'noun', NULL, 'uncountable; the usual verb is set in, as in scope creep has set in', 'Every extra chart they ask for is scope creep, and nobody is moving the deadline.', NULL, '["work","scope"]', 120, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0121', 'en', 'see where someone is coming from', 'understand the reasoning behind what someone says, even when you don''t agree with it', 'idiom', NULL, 'Informal but safe in meetings. The continuous form is fixed: ''where you come from'' means your home country, which is a different conversation entirely.', 'I can see where you''re coming from, since you''ve been burned by a rushed launch before.', NULL, '["meetings","disagreeing"]', 121, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0122', 'en', 'you alright?', 'a casual British greeting, not a question about your health', 'phrase', NULL, 'Answer "Yeah, you?" — reporting how you actually feel is the classic mistake here.', 'You alright? I haven''t seen you in ages.', NULL, '["social","uk","trap"]', 122, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0123', 'en', 'like-for-like', 'compared on the same basis, with known differences stripped out', 'adj', NULL, 'British retail and finance term; Americans say same-store or comparable. Hyphenated before a noun.', 'On a like-for-like basis the two regions are almost identical.', NULL, '["data","comparison"]', 123, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0124', 'en', 'rebate', 'money given back to you because you paid too much', 'noun', NULL, 'A rebate comes back after overpayment; a discount is taken off up front. Usually ''tax rebate'' or ''a rebate on the bill''.', 'I was on the wrong tax code all year, so a rebate should come through in June.', NULL, '["money","tax"]', 124, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0125', 'en', 'fit note', 'a doctor''s statement about whether you are well enough to work', 'noun', NULL, 'Officially replaced ''sick note'', though people still say sick note in conversation.', 'My GP gave me a fit note for two weeks.', NULL, '["life","healthcare","uk"]', 125, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0126', 'en', 'up to a point', 'used to agree partly but not completely', 'phrase', NULL, 'A gentle brake. Said on its own with no follow-up it can sound dismissive.', 'That''s true up to a point, though it breaks down for enterprise accounts.', NULL, '["glue","disagreeing","concession"]', 126, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0127', 'en', 'out of scope', 'outside the agreed boundaries of the work', 'phrase', NULL, 'opposite of in scope; both follow the verb be', 'Anything before 2019 is out of scope for this analysis.', NULL, '["work","scope"]', 127, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0128', 'en', 'sense-check', 'check quickly and informally that an idea or figure is reasonable before it goes further', 'verb', NULL, 'Chiefly British, and also a noun: ''a quick sense-check''. American colleagues say ''sanity check'', which is falling out of favour.', 'Can I sense-check this with you? These figures look too good.', NULL, '["meetings","checking-understanding","british"]', 128, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0129', 'en', 'not fussed', 'having no strong preference', 'phrase', NULL, 'Warm and British; "I don''t care" in the same slot sounds cold.', 'I''m not fussed where we eat, you choose.', NULL, '["social","food","uk"]', 129, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0130', 'en', 'proxy', 'a measurable stand-in for something you cannot measure directly', 'noun', NULL, 'Pattern: a proxy for X. Naming it out loud shows you know the measure is imperfect, which buys credibility.', 'We use session length as a proxy for engagement, which is crude but workable.', NULL, '["data","method"]', 130, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0131', 'en', 'allowance', 'an amount you may earn or use before a rule or charge starts to apply', 'noun', NULL, 'In tax and travel this is a threshold, not pocket money: personal allowance, baggage allowance, mileage allowance.', 'The first slice of your income falls under the personal allowance and isn''t taxed.', NULL, '["money","tax","work"]', 131, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0132', 'en', 'out of hours', 'outside normal opening or working times', 'phrase', NULL, 'Hyphenated before a noun: an out-of-hours service. Used for clinics, plumbers and helplines.', 'If it gets worse tonight, ring the out-of-hours number.', NULL, '["life","healthcare","service"]', 132, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0133', 'en', 'strictly speaking', 'used to give the exact, technically correct version of something', 'phrase', NULL, 'Can come across as pedantic if you use it to win small points.', 'Strictly speaking, it isn''t a bug — the spec never covered that case.', NULL, '["glue","hedging","signposting"]', 133, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0134', 'en', 'turnaround', 'the time needed to complete something and send it back', 'noun', NULL, 'one word as a noun: a quick turnaround; as a verb it splits: turn it around by Friday', 'They promise a two-day turnaround on any data request.', NULL, '["work","deadlines"]', 134, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0135', 'en', 'hold that thought', 'ask someone to keep an idea for a moment while something else is finished', 'phrase', NULL, 'Friendly and slightly informal. It promises you will come back within the same meeting; for anything longer, use ''park''.', 'Hold that thought while we get the numbers on screen, then you can explain.', NULL, '["meetings","interrupting","deferring"]', 135, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0136', 'en', 'to run something past someone', 'to show something to someone for their opinion before it goes out', 'verb', NULL, 'past, not passed. Americans say ''run by''.', 'Can I run the wording past you before I send it?', NULL, '["writing","work","trap"]', 136, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0137', 'en', 'knackered', 'extremely tired', 'adj', NULL, 'Very informal British. Fine with friends, avoid with a client.', 'I was knackered after the hike, so we had an early night.', NULL, '["social","register","uk"]', 137, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0138', 'en', 'granularity', 'the level of detail at which data is recorded or reported', 'noun', NULL, 'Adjective: granular. ''Can we go more granular?'' means can we break it down further.', 'We only have daily granularity, so the hourly question can''t be answered.', NULL, '["data","method"]', 138, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0139', 'en', 'net', 'left after tax and other deductions have been taken off', 'adj', NULL, 'Opposite of gross, the amount before deductions. Can follow the number: two thousand net.', 'The salary looks generous until you work out the net figure.', NULL, '["money","tax","work"]', 139, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0140', 'en', 'letting agent', 'a company that rents out a property for the owner and deals with tenants', 'noun', NULL, 'British. ''To let'' means for rent, hence the boards outside flats.', 'The letting agent takes a month''s rent as a fee.', NULL, '["life","housing","uk"]', 140, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0141', 'en', 'arguably', 'used to present a claim as defensible rather than certain', 'adv', NULL, 'Softens a bold claim; used on every sentence it makes you sound half-hearted.', 'This is arguably the cleanest dataset we have.', NULL, '["glue","hedging","writing"]', 141, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0142', 'en', 'to slip', 'to fall behind a planned date', 'verb', NULL, 'dates and deadlines slip by themselves, with no object; the noun is slippage', 'The launch date has slipped twice already.', NULL, '["work","deadlines"]', 142, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0143', 'en', 'iron out', 'resolve the small problems or disagreements left in something broadly agreed', 'verb', NULL, 'Only for minor wrinkles. If the disagreement is fundamental, ''thrash out'' or ''work through'' is the honest choice.', 'The contract is basically settled; we just need to iron out the payment terms.', NULL, '["meetings","negotiating"]', 143, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0144', 'en', 'to come across as', 'to give a particular impression, often without meaning to', 'verb', NULL, 'About how the reader receives it, not what you intended. This is the whole idea of tone in email.', 'That one-line reply comes across as colder than you meant.', NULL, '["writing","register"]', 144, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0145', 'en', 'a lie-in', 'a morning spent staying in bed later than usual', 'noun', NULL, 'You have a lie-in. Americans say sleep in.', 'The one thing I want at the weekend is a proper lie-in.', NULL, '["social","weekend","uk"]', 145, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0146', 'en', 'spurious', 'looking genuine but in fact false', 'adj', NULL, 'Formal. The standard pair is spurious correlation. Too strong for an honest slip: it implies the finding is worthless.', 'With enough variables you will find a spurious correlation sooner or later.', NULL, '["data","uncertainty"]', 146, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0147', 'en', 'pro rata', 'in proportion to the time or share involved', 'adv', NULL, 'Common in contracts and part-time adverts: ''thirty thousand pro rata'' is the full-time rate scaled to your hours.', 'If you cancel halfway through the year, the fee is refunded pro rata.', NULL, '["money","contracts","work"]', 147, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0148', 'en', 'tenancy agreement', 'the contract between tenant and landlord setting out rent and rules', 'noun', NULL, 'British for ''lease''. The tenancy is the arrangement; you are the tenant.', 'Read the tenancy agreement before you sign anything about pets.', NULL, '["life","housing","admin"]', 148, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0149', 'en', 'flag (something to someone)', 'to draw attention to something so that others can act on it', 'verb', NULL, 'British English also uses ''flag up''. The standard office verb for raising an issue without escalating it.', 'I''ll flag the missing region codes to the data team this morning.', NULL, '["glue","work","signposting","british"]', 149, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0150', 'en', 'dependency', 'something your work cannot start or finish without', 'noun', NULL, 'a dependency ON something; in plans it is usually plural', 'Our only dependency is the new data feed, and it isn''t ready.', NULL, '["work","blockers"]', 150, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0151', 'en', 'nail down', 'make something vague definite, such as a date, a number or a commitment', 'verb', NULL, 'Also used of people: ''I couldn''t nail him down to a date'' means he kept avoiding the commitment.', 'Before we leave, can we nail down who is presenting on Monday?', NULL, '["meetings","decisions"]', 151, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0152', 'en', 'curt', 'so short that it sounds rude', 'adj', NULL, 'In British email the usual cause is a one-line reply with no greeting.', 'His answer was accurate but curt, so I softened the opening line.', NULL, '["writing","register"]', 152, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0153', 'en', 'peckish', 'slightly hungry', 'adj', NULL, 'British and understated — far milder than starving.', 'I''m getting a bit peckish — shall we find somewhere?', NULL, '["social","food","uk"]', 153, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0154', 'en', 'conflate', 'to treat two distinct things as if they were one', 'verb', NULL, 'Pattern: conflate A with B. Handy in review, and politer than telling someone they are confused.', 'The slide conflates new users with reactivated ones.', NULL, '["data","argument"]', 154, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0155', 'en', 'instalment', 'one of several smaller payments spread over time', 'noun', NULL, 'One ''l'' in British spelling, two in American. The fixed phrase is ''pay in instalments''.', 'They let me pay the deposit in three monthly instalments.', NULL, '["money","banking","contracts"]', 155, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0156', 'en', 'notice period', 'how far in advance you must tell the other side you are ending an agreement', 'noun', NULL, 'Also used about jobs. ''Give notice'' means formally announce you are leaving.', 'There''s a two-month notice period, so tell them by the end of March.', NULL, '["life","housing","admin"]', 156, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0157', 'en', 'on balance', 'after weighing both sides, taken as a whole', 'phrase', NULL, 'Marks a conclusion after the pros and cons, so it shouldn''t open the discussion.', 'On balance, I''d keep the old pipeline until the migration settles.', NULL, '["glue","signposting","concluding"]', 157, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0158', 'en', 'bottleneck', 'the one slow step that holds up everything after it', 'noun', NULL, 'about a stage or resource, not a person''s character', 'Manual approval is the bottleneck, not the analysis.', NULL, '["work","blockers"]', 158, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0159', 'en', 'flesh out', 'add the missing detail to an idea that exists only in outline', 'verb', NULL, 'Watch the spelling. ''Flush out'' means force something into the open and is a completely different verb.', 'The concept is good; flesh it out with costs and I''ll take it to the board.', NULL, '["meetings","developing-ideas"]', 159, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0160', 'en', 'as discussed', 'referring back to something already agreed in conversation', 'phrase', NULL, '''As per our discussion'' is stiffer and can read as building a case against the reader.', 'As discussed, I''ve attached the revised figures.', NULL, '["writing","email"]', 160, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0161', 'en', 'I''ll let you get on', 'a polite way to end a conversation with someone who is busy', 'phrase', NULL, '"Get on" here means carry on with what they were doing.', 'Right, I''ll let you get on — we''ll speak next week.', NULL, '["social","leaving","uk"]', 161, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0162', 'en', 'confounder', 'a hidden third factor that drives both things you are comparing', 'noun', NULL, 'Also confounding variable, and the verb confound. ''Controlling for confounders'' is the fixed phrase.', 'Region is an obvious confounder here: the two groups aren''t drawn from the same market.', NULL, '["data","method","causation"]', 162, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0163', 'en', 'lump sum', 'a single large payment made all at once', 'noun', NULL, 'The natural opposite of instalments; used for pensions, bonuses and annual subscriptions.', 'Paying the year up front as a lump sum works out about ten per cent cheaper.', NULL, '["money","banking","subscriptions"]', 163, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0164', 'en', 'wear and tear', 'the normal damage that comes from ordinary use over time', 'phrase', NULL, 'Nearly always in the fixed phrase ''fair wear and tear'' — what a landlord may not deduct from your deposit.', 'Faded paint is fair wear and tear, so they can''t charge you for it.', NULL, '["life","housing"]', 164, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0165', 'en', 'correct me if I''m wrong', 'used before a statement you believe is true, inviting the other person to correct it', 'phrase', NULL, 'A polite way to challenge someone: you sound tentative while still making the point.', 'Correct me if I''m wrong, but this table hasn''t refreshed since Friday.', NULL, '["glue","hedging","disagreeing","spoken"]', 165, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0166', 'en', 'workaround', 'a temporary way of getting past a problem without fixing it', 'noun', NULL, 'one word as a noun; the verb is two words: work around the problem', 'We have a workaround, but it won''t survive the next release.', NULL, '["work","blockers"]', 166, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0167', 'en', 'run through (something)', 'go over a list or a set of points quickly, from start to finish', 'verb', NULL, 'Noun form: ''a quick run-through''. ''Run through'' is a fast preview; ''go through'' suggests something slower and more thorough.', 'I''ll run through the agenda first so you know what''s coming.', NULL, '["meetings","summarising"]', 167, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0168', 'en', 'no rush', 'a signal that the request is not urgent', 'phrase', NULL, 'Takes the pressure off, but it will be taken literally, so add a real date if one exists.', 'Have a look when you get a chance; no rush.', NULL, '["writing","chasing","register"]', 168, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0169', 'en', 'to go down well', 'to be received positively', 'idiom', NULL, 'Works equally for food, jokes, news and presentations.', 'The dessert went down very well with everyone.', NULL, '["social","food"]', 169, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0170', 'en', 'anecdotal', 'based on scattered individual reports rather than systematic evidence', 'adj', NULL, 'Anecdotal evidence is the set phrase. Mildly dismissive, so soften it: ''this is still anecdotal, but...''.', 'So far the complaints are anecdotal; I want to see whether the tickets back them up.', NULL, '["data","evidence"]', 170, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0171', 'en', 'rolling contract', 'an agreement that continues automatically until one side ends it', 'noun', NULL, '''Rolling'' is the key word: a rolling subscription rolls over each month. Compare ''fixed-term'', which ends on a set date.', 'It''s a rolling monthly contract, so you can leave whenever you like with thirty days'' notice.', NULL, '["money","contracts","subscriptions"]', 171, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0172', 'en', 'break clause', 'a term in a contract letting either side end it early', 'noun', NULL, 'You ''exercise'' or ''trigger'' a break clause. Common in rentals and phone contracts.', 'There''s a break clause at six months if the job falls through.', NULL, '["life","housing","admin"]', 172, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0173', 'en', 'long story short', 'used to skip the detail and jump to the outcome', 'phrase', NULL, 'Keep the promise — whatever follows should genuinely be short.', 'Long story short, the join was duplicating rows.', NULL, '["glue","signposting","spoken"]', 173, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0174', 'en', 'to park', 'to set something aside deliberately to return to it later', 'verb', NULL, 'in a meeting, park it means come back to it, not drop it', 'Can we park the pricing question until we have the numbers?', NULL, '["work","priorities"]', 174, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0175', 'en', 'talk over someone', 'keep speaking while another person is speaking, so they cannot be heard', 'verb', NULL, 'Word order changes the meaning completely: ''talk something over'' means discuss it properly, while ''talk over someone'' is rude.', 'Sorry, I talked over you there. Please finish.', NULL, '["meetings","interrupting"]', 175, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0176', 'en', 'thread', 'a chain of replies kept under one message or topic', 'noun', NULL, '''Reply in thread'' means do not post it to the whole channel.', 'Let''s keep this in the thread so the channel stays readable.', NULL, '["writing","slack"]', 176, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0177', 'en', 'moreish', 'so tasty that you keep wanting more', 'adj', NULL, 'British; it compliments the food rather than criticising the eater.', 'Those little cheese pastries are dangerously moreish.', NULL, '["social","food","uk"]', 177, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0178', 'en', 'cherry-pick', 'to choose only the cases that support your argument', 'verb', NULL, 'An accusation about method, not a word for an innocent mistake. Hyphenated in British usage.', 'If you cherry-pick the two best weeks, of course the campaign looks brilliant.', NULL, '["data","argument"]', 178, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0179', 'en', 'auto-renew', 'to continue for another period automatically unless you cancel', 'verb', NULL, 'Noun: auto-renewal. Usually the detail people miss: it auto-renewed and they were charged for another year.', 'The trial auto-renews into a yearly plan, so cancel before the tenth.', NULL, '["money","subscriptions","contracts"]', 179, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0180', 'en', 'play up', 'to work badly or cause trouble, of a device, a body part or a child', 'idiom', NULL, 'British and informal, but fine with a landlord or a doctor: my knee''s playing up again.', 'The boiler''s been playing up since the cold snap.', NULL, '["life","housing","uk"]', 180, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0181', 'en', 'for what it''s worth', 'used to offer an opinion while playing down its importance', 'phrase', NULL, 'Modest on the surface, but often used to slip in a strong opinion.', 'For what it''s worth, I''d run the test for another week.', NULL, '["glue","softening","spoken"]', 181, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0182', 'en', 'remit', 'the area of work someone is officially responsible for', 'noun', NULL, 'formal and distinctly British; the usual complaint is that''s outside my remit', 'Pricing sits outside my remit, but I can point you to the right team.', NULL, '["work","ownership","uk"]', 182, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0183', 'en', 'break up', 'of a voice on a call: become fragmented and hard to hear because the connection is poor', 'verb', NULL, 'Fixed in the continuous: ''you''re breaking up''. Compare ''you cut out'', where the sound disappeared altogether.', 'You''re breaking up. Could you turn your camera off and try again?', NULL, '["meetings","calls"]', 183, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0184', 'en', 'to ping', 'to send a short message to get someone''s attention', 'verb', NULL, 'Internal chat only. You would never write that you will ping a client.', 'Ping me when the export finishes.', NULL, '["writing","slack","register"]', 184, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0185', 'en', 'spoilt for choice', 'having so many good options that choosing is hard', 'idiom', NULL, 'British spelling spoilt; American English writes spoiled.', 'With three markets within walking distance, we''re spoilt for choice.', NULL, '["social","food","uk"]', 185, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0186', 'en', 'inconclusive', 'not clear enough to settle the question either way', 'adj', NULL, 'Says the analysis was sound but the answer isn''t there. Much weaker, and safer, than claiming no effect.', 'The test is inconclusive: the effect could be anywhere between nothing and six per cent.', NULL, '["data","uncertainty"]', 186, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0187', 'en', 'damp', 'unwanted moisture in the walls or structure of a building', 'noun', NULL, 'Uncountable noun as well as an adjective: ''we have damp'' is normal. Related: mould (US mold), condensation.', 'There''s damp behind the wardrobe and the plaster has gone black.', NULL, '["life","housing","uk"]', 187, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0188', 'en', 'mind you', 'used to add a qualifying afterthought to what you have just said', 'phrase', NULL, 'Strongly British and conversational; starts the qualifying clause or the next sentence.', 'It''s much faster now — mind you, it hasn''t had any real load yet.', NULL, '["glue","contrast","british","spoken"]', 188, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0189', 'en', 'to be on the hook for', 'to be the one who will be blamed if something goes wrong', 'idiom', NULL, 'informal; implies responsibility you did not necessarily want', 'If the figures are wrong, I''m on the hook for it, not the tool.', NULL, '["work","ownership"]', 189, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0190', 'en', 'overrun', 'continue past the time something was supposed to finish', 'verb', NULL, 'Chiefly British; Americans say ''run over''. Stress the second syllable as a verb and the first as a noun (''a slight overrun'').', 'The review overran by twenty minutes and I missed the start of your call.', NULL, '["meetings","time","british"]', 190, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0191', 'en', 'bland', 'lacking flavour or character', 'adj', NULL, 'Also used about films, design and writing.', 'The soup was warm but pretty bland.', NULL, '["social","food"]', 191, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0192', 'en', 'read too much into', 'to draw a bigger conclusion from something than it can support', 'phrase', NULL, 'Nearly always negative or conditional: don''t or wouldn''t read too much into. A polite brake on an eager stakeholder.', 'I wouldn''t read too much into a single week''s dip.', NULL, '["data","hedging"]', 192, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0193', 'en', 'terminate', 'to end a contract formally', 'verb', NULL, 'Legal register — for contracts and services, not for a meeting or a subscription you casually drop. In speech, use cancel or end.', 'Either side can terminate the agreement with sixty days'' written notice.', NULL, '["money","contracts","admin"]', 193, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0194', 'en', 'park (a topic)', 'to set something aside deliberately and return to it later', 'verb', NULL, 'Meeting shorthand: ''let''s park that''. It sounds dismissive if the topic is never unparked.', 'Can we park the naming question and finish the schema first?', NULL, '["glue","buying-time","work","british"]', 194, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0195', 'en', 'handover', 'the passing of work and knowledge to whoever takes it on next', 'noun', NULL, 'one word as a noun, two as a verb: hand over the project', 'We''ve got one week for a proper handover before she leaves.', NULL, '["work","ownership"]', 195, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0196', 'en', 'talk at cross purposes', 'appear to be having one conversation while in fact meaning two different things', 'idiom', NULL, 'Nearly always ''we''re talking at cross purposes'', which lets both sides retreat from a confused argument. ''Purposes'' is always plural.', 'I think we''re talking at cross purposes: I meant the client''s deadline, not ours.', NULL, '["meetings","checking-understanding"]', 196, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0197', 'en', 'COB', 'close of business, the end of the working day used as a deadline', 'noun', NULL, 'British-leaning; EOD is the American equivalent. Always add the time zone with spread-out teams.', 'Could you send the draft by COB Wednesday?', NULL, '["writing","work","email"]', 197, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0198', 'en', 'muggy', 'unpleasantly warm and humid', 'adj', NULL, NULL, 'It''s been muggy all week and I can''t sleep.', NULL, '["social","weather"]', 198, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0199', 'en', 'sanity check', 'a quick rough test that a number is not obviously wrong', 'noun', NULL, 'Also a verb: sanity-check the query. Informal but standard at work; some teams prefer ''quick check'' in writing.', 'As a sanity check, the totals should add up to the figure on the invoice.', NULL, '["data","method"]', 199, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0200', 'en', 'waive', 'to choose not to charge or enforce something you had the right to', 'verb', NULL, 'Waive a fee, a charge, a requirement, your rights. Not the same word as ''wave''; the noun is waiver.', 'They waived the transfer fee because the delay was their fault.', NULL, '["money","contracts","banking"]', 200, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0201', 'en', 'meter reading', 'the number shown on your gas, water or electricity meter, given to the supplier', 'noun', NULL, 'Verb: read the meter. Estimated bills are why this comes up so often.', 'Send them a meter reading or they''ll carry on estimating the bill.', NULL, '["life","utilities"]', 201, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0202', 'en', 'admittedly', 'used to acknowledge a weakness in your own argument', 'adv', NULL, 'More formal than ''granted'' and comfortable in written reports.', 'The method is slow, admittedly, but it''s the only one we can audit.', NULL, '["glue","concession","writing"]', 202, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0203', 'en', 'play devil''s advocate', 'argue the opposite case on purpose, to test how strong an idea really is', 'idiom', NULL, 'Announce it before you argue, otherwise people assume the objection is genuinely yours.', 'Let me play devil''s advocate for a second: what if users never find the new button?', NULL, '["meetings","disagreeing"]', 203, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0204', 'en', 'to action', 'to deal with a request', 'verb', NULL, 'A noun turned into a verb. Widespread in British offices, disliked by careful writers; ''deal with'' is safer.', 'The request was actioned the same afternoon.', NULL, '["writing","register","trap"]', 204, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0205', 'en', 'drizzle', 'fine, light rain', 'noun', NULL, 'Also a verb: it''s drizzling. In cooking it means to pour a thin stream of oil.', 'It''s only drizzle, we can still walk down.', NULL, '["social","weather"]', 205, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0206', 'en', 'back-of-the-envelope', 'worked out roughly, without precision', 'adj', NULL, 'Used before a noun: a back-of-the-envelope figure. Flags honestly that the number is approximate.', 'A back-of-the-envelope estimate puts the saving at about two days a month.', NULL, '["data","estimation"]', 206, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0207', 'en', 'binding', 'legally forcing both sides to do what they agreed', 'adj', NULL, 'Usually ''legally binding''. ''Non-binding'' marks a document as an intention only, such as a draft offer.', 'Once you tick the box and confirm, the quote becomes binding.', NULL, '["money","contracts"]', 207, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0208', 'en', 'in arrears', 'behind with payments that are already due', 'phrase', NULL, 'Formal, common in letters. It also means paid at the end of a period: rent paid in arrears.', 'The account is two months in arrears, so they''ve frozen it.', NULL, '["life","utilities","money"]', 208, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0209', 'en', 'come to think of it', 'used when something occurs to you as you are speaking', 'phrase', NULL, 'Makes an idea sound spontaneous rather than prepared, which lowers the stakes of raising it.', 'Come to think of it, the same thing happened after the last release.', NULL, '["glue","spoken","afterthought"]', 209, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0210', 'en', 'go off on a tangent', 'drift away from the topic into something only loosely related', 'idiom', NULL, 'The older British form is ''go off at a tangent'' and is still heard. Useful when steering a meeting back: ''I''ve gone off on a tangent, sorry.''', 'We went off on a tangent about hiring and never got back to the budget.', NULL, '["meetings","steering"]', 210, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0211', 'en', 'to chuck it down', 'to rain very heavily', 'idiom', NULL, 'Informal British and always with "it": it''s chucking it down.', 'We got to the door just as it started chucking it down.', NULL, '["social","weather","uk"]', 211, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0212', 'en', 'order of magnitude', 'a factor of roughly ten; the rough scale of a number rather than its exact size', 'phrase', NULL, '''An order of magnitude larger'' means about ten times larger. Don''t stretch it to mean ''a bit bigger''.', 'We only need the order of magnitude here: is it hundreds or thousands?', NULL, '["data","estimation"]', 212, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0213', 'en', 'the small print', 'the detailed conditions of a contract, where the awkward rules sit', 'idiom', NULL, 'British; Americans say ''the fine print''. Normally with read or check, and it implies something unwelcome is buried there.', 'The offer looked great until I read the small print and found the exit fee.', NULL, '["money","contracts","insurance"]', 213, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0214', 'en', 'top up', 'to add money or credit to something so it is full again', 'verb', NULL, 'British; the noun is ''a top-up''. Used for phone credit, travel cards and drinks too.', 'I need to top up the electricity key before the weekend.', NULL, '["life","utilities","phrasal-verb"]', 214, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0215', 'en', 'just to be clear', 'used before restating something to remove any misunderstanding', 'phrase', NULL, 'Tone-sensitive: delivered flatly it reads as a correction or a warning shot.', 'Just to be clear, we''re only changing the weekly view, not the daily one.', NULL, '["glue","signposting","clarifying","work"]', 215, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0216', 'en', 'buffer', 'extra time built into a plan in case something goes wrong', 'noun', NULL, 'the usual collocation is build in a buffer', 'There''s no buffer in this plan, so one bad week sinks it.', NULL, '["work","deadlines"]', 216, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0217', 'en', 'thrash something out', 'discuss a difficult issue at length until an agreement is reached', 'verb', NULL, 'Chiefly British, and the tone implies real effort. Americans say ''hash out'' for the same thing.', 'We spent the whole afternoon thrashing out who owns the data.', NULL, '["meetings","negotiating","british"]', 217, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0218', 'en', 'Please find attached', 'a formal way to introduce a file you are sending', 'phrase', NULL, 'Old-fashioned. ''I''ve attached the contract'' reads better in modern British email.', 'Please find attached the signed contract.', NULL, '["writing","email","register"]', 218, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0219', 'en', 'to brighten up', 'to become sunnier, or more cheerful', 'verb', NULL, 'Used of weather, of rooms and of people.', 'They reckon it''ll brighten up by lunchtime.', NULL, '["social","weather"]', 219, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0220', 'en', 'headline figure', 'the single number quoted publicly, before any adjustment', 'noun', NULL, 'British reporting language and the natural opposite of underlying. Also headline rate, headline number.', 'The headline figure is forty per cent growth; the like-for-like number is nearer twelve.', NULL, '["data","presenting"]', 220, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0221', 'en', 'proof of address', 'a document showing where you live, required to open accounts', 'noun', NULL, 'Usually a recent utility bill or bank statement. Goes with ''proof of identity'' and ''photo ID''.', 'They wouldn''t open the account without proof of address dated in the last three months.', NULL, '["life","bureaucracy","admin"]', 221, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0222', 'en', 'namely', 'used to specify exactly who or what you mean', 'adv', NULL, 'Introduces the complete list; ''such as'' introduces examples only.', 'Two markets are dragging the average down, namely Spain and Poland.', NULL, '["glue","signposting","writing"]', 222, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0223', 'en', 'to be snowed under', 'to have far more work than you can reasonably handle', 'idiom', NULL, 'British and informal; snowed under WITH work, and always passive', 'I''m snowed under until Thursday, so anything new will have to wait.', NULL, '["work","priorities","uk"]', 223, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0224', 'en', 'have reservations (about something)', 'have doubts you are prepared to state, without rejecting the idea outright', 'phrase', NULL, 'Formal and measured, and it survives well in written minutes. Usually ''some reservations'' or ''serious reservations''.', 'I have reservations about launching in August, though I won''t block it.', NULL, '["meetings","disagreeing","formal"]', 224, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0225', 'en', 'at your earliest convenience', 'as soon as you reasonably can', 'phrase', NULL, 'Polite but distant and vague. If you need a date, write the date.', 'Please confirm the figures at your earliest convenience.', NULL, '["writing","email","chasing"]', 225, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0226', 'en', 'mild', 'pleasantly not cold for the season', 'adj', NULL, 'In weather talk it is a compliment; about food the same word means not spicy.', 'It''s been a very mild winter here.', NULL, '["social","weather","trap"]', 226, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0227', 'en', 'mask', 'to hide a real pattern behind a summary figure', 'verb', NULL, '''The average masks...'' is a workhorse opening for any analyst. Near neighbours: obscure, conceal.', 'The flat average masks a sharp split between new and returning customers.', NULL, '["data","presenting"]', 227, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0228', 'en', 'sign off', 'to approve something officially, usually spending or a document', 'verb', NULL, 'In this sense it takes ''on'': sign off on the budget. Bare ''sign off'' can also mean ending a message, or in Britain being declared unfit for work.', 'Finance has to sign off on any purchase over a thousand euros.', NULL, '["money","work","admin"]', 228, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0229', 'en', 'be entitled to', 'to have an official right to something', 'phrase', NULL, 'Officialese, everywhere in letters. But calling a person ''entitled'' is an insult: they think they deserve special treatment.', 'As a resident you''re entitled to the same cover as anyone else.', NULL, '["life","bureaucracy","register"]', 229, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0230', 'en', 'to triage', 'to sort tasks by urgency before deciding what to do', 'verb', NULL, 'borrowed from medicine; it means sorting, not solving', 'Let''s triage the requests first and see what actually needs doing this week.', NULL, '["work","priorities"]', 230, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0231', 'en', 'with all due respect', 'a formal opening that signals firm disagreement, usually with someone more senior', 'phrase', NULL, 'A trap. It sounds courteous but almost always precedes a blunt contradiction, and British listeners often hear it as combative. ''I''d see it slightly differently'' is safer.', 'With all due respect, the figures in that report are three months old.', NULL, '["meetings","disagreeing","register-trap"]', 231, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0232', 'en', 'in due course', 'at some suitable point later, with no date promised', 'phrase', NULL, 'A British hedge: the reader will correctly hear ''not soon''.', 'We''ll share the full results in due course.', NULL, '["writing","register"]', 232, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0233', 'en', 'a quiet one', 'an evening or weekend spent doing very little', 'noun', NULL, 'Usually "we had a quiet one" — a normal, positive answer to the weekend question.', 'We had a quiet one, just a film and an early night.', NULL, '["social","weekend","uk"]', 233, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0234', 'en', 'offset', 'to cancel out part or all of a movement in the opposite direction', 'verb', NULL, 'Usually passive: X was offset by Y. Stress differs by word class: OFF-set the noun, off-SET the verb.', 'Losses in the north were offset by a strong quarter in Lisbon.', NULL, '["data","trends"]', 234, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0235', 'en', 'overdrawn', 'having taken more money out of an account than it contained', 'adj', NULL, 'Adjective for you or the account; the arrangement itself is ''an overdraft''. Informally, ''in the red''.', 'The subscription went out before payday and left me overdrawn.', NULL, '["money","banking"]', 235, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0236', 'en', 'then again', 'used to introduce a thought that undercuts what you have just said', 'phrase', NULL, 'Signals thinking aloud, which makes a change of position sound reasonable rather than inconsistent.', 'We could rebuild it properly — then again, nobody has opened that report in months.', NULL, '["glue","contrast","spoken"]', 236, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0237', 'en', 'to get something over the line', 'to finish something that is almost complete', 'idiom', NULL, 'British; suits the last push on a project, not the start of one', 'One more review and we can get this over the line.', NULL, '["work","deadlines","uk"]', 237, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0238', 'en', 'table (something)', 'in British usage, to put a proposal forward formally for discussion', 'verb', NULL, 'A genuine transatlantic trap: in American English, tabling something means postponing it indefinitely, the opposite meaning. On mixed calls, say ''put forward'' or ''postpone'' and avoid the word.', 'The finance team tabled a revised budget at yesterday''s board meeting.', NULL, '["meetings","register-trap","british"]', 238, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0239', 'en', 'I hope this finds you well', 'a neutral opening pleasantry in an email', 'phrase', NULL, 'Harmless but empty; British colleagues will not miss it if you go straight to the point.', 'I hope this finds you well. I''m writing about next month''s workshop.', NULL, '["writing","email","register"]', 239, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0240', 'en', 'to potter about', 'to spend time on small, unhurried tasks', 'verb', NULL, 'British; potter around is equally correct. Americans say putter.', 'I spent Sunday pottering about in the garden.', NULL, '["social","weekend","uk"]', 240, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0241', 'en', 'knock-on effect', 'a consequence that follows indirectly from an earlier change', 'noun', NULL, 'British; Americans say ripple effect. Knock-on also works as an adjective: knock-on costs, knock-on delays.', 'The pricing change had a knock-on effect on support volumes.', NULL, '["data","causation"]', 241, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0242', 'en', 'shop around', 'to compare prices from several providers before buying', 'verb', NULL, 'Phrasal verb with no object: shop around for car insurance. Standard advice about insurance, energy and mobile plans.', 'Shop around before the policy renews instead of accepting whatever price they send you.', NULL, '["money","insurance","subscriptions"]', 242, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0243', 'en', 'ombudsman', 'an independent official who investigates complaints against companies or public bodies', 'noun', NULL, 'Usually free, and only available once the company''s own complaints process is exhausted.', 'If they reject the claim, take it to the ombudsman.', NULL, '["life","complaints","bureaucracy"]', 243, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0244', 'en', 'at a push', 'if it is really necessary, though it would be a stretch', 'phrase', NULL, 'British; it warns that you are agreeing at the very limit of what''s possible.', 'I could have a draft ready by Thursday at a push.', NULL, '["glue","hedging","british","spoken"]', 244, NULL, 'glue') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0245', 'en', 'nice-to-have', 'a feature that would be welcome but is not required', 'noun', NULL, 'hyphenated as a noun and usually set against a must-have', 'Real-time refresh is a nice-to-have, not a requirement.', NULL, '["work","scope"]', 245, NULL, 'work') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0246', 'en', 'AOB', 'any other business: the slot near the end of an agenda for items nobody listed in advance', 'noun', NULL, 'Standard on British agendas and minutes, said as three separate letters. With an international group, say the full ''any other business'' at least once.', 'We''ve got five minutes for AOB if anyone has something short.', NULL, '["meetings","agenda","british"]', 246, NULL, 'meetings') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0247', 'en', 'to word', 'to choose the exact way something is expressed', 'verb', NULL, 'Use this, not ''formulate'', which sounds academic. The noun is the wording.', 'I''d word that last paragraph more carefully.', NULL, '["writing","register","trap"]', 247, NULL, 'writing') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0248', 'en', 'to hit it off', 'to like each other immediately', 'idiom', NULL, 'Add with for the other person: they hit it off with the new team.', 'We hit it off straight away and talked for an hour.', NULL, '["social","smalltalk"]', 248, NULL, 'social') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0249', 'en', 'take with a pinch of salt', 'to treat something as unreliable and not act on it fully', 'idiom', NULL, 'British form; Americans say a grain of salt. Fine spoken in a meeting, too casual for a written report.', 'Take the first day of data with a pinch of salt, as the tagging was still settling.', NULL, '["data","hedging"]', 249, NULL, 'data') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0250', 'en', 'out of pocket', 'personally worse off in money terms after paying for something', 'idiom', NULL, 'British usage is strictly about losing your own money. In American English it can also mean unreachable, which causes real confusion by email.', 'If the refund never arrives, I''m forty euros out of pocket.', NULL, '["money","work","admin"]', 250, NULL, 'money') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('en0251', 'en', 'flag up', 'to draw attention to a problem early so that it is not missed', 'verb', NULL, 'British; Americans say ''flag'' or ''raise''. Useful when you want proof that you warned someone.', 'I flagged up the damp when I moved in, and it''s all in the email.', NULL, '["life","complaints","phrasal-verb"]', 251, NULL, 'life') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0001', 'pt', 'dá para...?', 'is it possible to...? / can we...?', 'phrase', NULL, 'the everyday way to ask if something is doable; textbooks never teach it', 'Dá para pagar com multibanco?', 'Can I pay by card?', '["frase","core"]', 300, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0002', 'pt', 'tenho de ir', 'I have to go', 'phrase', NULL, 'pt-PT prefers ter de over ter que', 'Desculpe, tenho de ir andando.', 'Sorry, I have to get going.', '["frase","core"]', 301, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0003', 'pt', 'está bem', 'all right, okay', 'phrase', NULL, 'the universal agreement noise; often just ''tá bem''', 'Amanhã às nove? Está bem.', 'Tomorrow at nine? All right.', '["frase","core"]', 302, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0004', 'pt', 'não faz mal', 'never mind, no harm done', 'phrase', NULL, 'what you say when someone apologises', 'Chegaste tarde? Não faz mal.', 'You came late? Never mind.', '["frase","core"]', 303, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0005', 'pt', 'se calhar', 'maybe, perhaps', 'phrase', NULL, 'far more common in Portugal than talvez', 'Se calhar vou amanhã.', 'Maybe I''ll go tomorrow.', '["frase","pt-pt"]', 304, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
