INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('fr0007', 'pt', 'logo se vê', 'we''ll see later', 'phrase', NULL, 'the national approach to planning', 'Ainda não sei. Logo se vê.', 'I don''t know yet. We''ll see.', '["frase","pt-pt"]', 306, NULL, 'frases') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
